def parse_sensor_reading(reading):
    """Parses a sensor reading string into a dict with keys 'temperature', 'humidity', and 'timestamp'."""
    if reading is None or not isinstance(reading, str):
        return None
    parts = reading.split('|')
    data = {'temperature': None, 'humidity': None, 'timestamp': None}
    for part in parts:
        if part.startswith("T:"):
            try:
                data['temperature'] = float(part[2:])
            except (ValueError, TypeError):
                data['temperature'] = None
        elif part.startswith("H:"):
            try:
                data['humidity'] = float(part[2:])
            except (ValueError, TypeError):
                data['humidity'] = None
        elif part.startswith("TS:"):
            data['timestamp'] = part[3:]
    return data

def aggregate_temperature(readings):
    """Aggregates temperature values from sensor readings and returns the average rounded to 2 decimals."""
    if not isinstance(readings, list) or len(readings) == 0:
        return None
    temps = []
    for reading in readings:
        parsed = parse_sensor_reading(reading)
        if not parsed:
            continue
        temp = parsed.get('temperature')
        if isinstance(temp, (int, float)):
            temps.append(temp)
    if not temps:
        return None
    avg = sum(temps) / len(temps)
    return round(avg, 2)

